\group{Cellular Homology}

\[
H_n^{CW}(X)\cong H_n(X).
\]
\end{theorem}
\begin{proof}
\sketch The maps $j_n$ identify $H_n(X^n)$ with $\ker\partial_n$ and carry $\operatorname{Im}\partial_{n+1}$ onto $\operatorname{Im}d_{n+1}$, yielding the quotient isomorphism.
